import java.util.*;
import java.math.BigInteger;

public class Main {
    static Scanner scanner = new Scanner(System.in);

    static long factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result.longValue();
    }

    static long A(int n, int k) {
        return factorial(n) / factorial(n - k);
    }

    public static void main(String[] args) {
        int n = scanner.nextInt();
        int mod = scanner.nextInt();

        if (n == 1) {
            System.out.println(0);
            return;
        }

        long[] z = {1};
        long aaa = 0;

        for (int i = 2; i <= n; i++) {
            int size = i * i / 2;
            long[] nz = new long[size];
            for (int j = 0; j < z.length; j++) {
                for (int k = 0; k < i; k++) {
                    if (z[j] > 0) {
                        int index = i - k - 1 + j;
                        if (index >= 0 && index < nz.length) {
                            nz[index] += z[j];
                        }
                    }
                }
            }

            long[] d = new long[z.length + 1];
            d[z.length] = 0;
            for (int w = z.length - 1; w >= 0; w--) {
                d[w] = (d[w + 1] + z[w]) % mod;
            }

            long[] e = new long[d.length];
            long[] f = new long[d.length];
            e[0] = 0;
            f[0] = 0;
            for (int w = 0; w < d.length - 1; w++) {
                e[w + 1] = (e[w] + d[w]) % mod;
                f[w + 1] = (f[w] - w * d[w]) % mod;
            }

            long bbb = 0;
            for (int jj = 0; jj < z.length; jj++) {
                long ccc = 0;
                int L = jj + 2;
                int R = Math.min(z.length - 1, i + jj);
                if (R >= L) {
                    long deltaE = (e[R + 1] - e[L]) % mod;
                    long deltaF = (f[R + 1] - f[L]) % mod;
                    ccc = (ccc + (deltaE * (i + 1 + jj) + deltaF) % mod) % mod;
                }
                bbb = (bbb + ccc * z[jj]) % mod;
            }

            aaa = (aaa + bbb * A(n, n - i)) % mod;
            z = nz;
        }

        System.out.println(aaa % mod);
    }
}

